  Definition pendingP (M : word -> option byte) (k : nat) (w : word) : Prop :=
    rdn RSEGS M (Z_to_bv 64 0x1588b8) (2 * k) = Some (zero_lines k) /\ bv_unsigned w = (0x1588b8 + 2 * Z.of_nat k)%Z /\ (k <= 3)%nat.

